"""Text helpers shared by the ingest readers."""

FORMAT_TAG = "# format:"


def clean_number(raw):
    """Turn a v1 feed amount into a plain decimal string ("1.234,56" -> "1234.56")."""
    return raw.strip().replace(".", "").replace(",", ".")


def plain_number(raw):
    """Turn a v2 feed amount into a plain decimal string ("1234.56" -> "1234.56").

    v2 exports drop thousands grouping and always use "." as the decimal mark,
    so the amount is already plain: stripping separators here would scale it.
    """
    return raw.strip()


def squash(s):
    """Collapse runs of whitespace."""
    return " ".join(s.split())


def feed_lines(text):
    """Split a feed body into (declared format, data lines)."""
    version = None
    lines = []
    for line in text.splitlines():
        if line.startswith(FORMAT_TAG):
            version = line[len(FORMAT_TAG):].strip()
        elif line and not line.startswith("#"):
            lines.append(line)
    return version, lines

"""Reader for the APAC ledger export (pipe-separated)."""
from decimal import Decimal

from meridian import text


def _strip_grouping(raw):
    # APAC v1 exports group thousands with spaces and use a decimal comma: "1 234,56"
    return raw.strip().replace(" ", "").replace(".", "").replace(",", ".")


AMOUNT_PARSERS = {"v1": _strip_grouping, "v2": text.plain_number}


def load(path):
    """Read an APAC feed: a list of {date, account, amount} rows."""
    with open(path, encoding="utf-8") as f:
        version, lines = text.feed_lines(f.read())
    if version not in AMOUNT_PARSERS:
        raise ValueError("%s: unsupported feed format %r" % (path, version))
    parse_amount = AMOUNT_PARSERS[version]
    out = []
    for line in lines:
        if line.startswith("date|"):
            continue
        date, account, amount = line.split("|")
        out.append({"date": date, "account": account, "amount": Decimal(parse_amount(amount))})
    return out

